// Décide si une action doit être validée par un humain avant exécution.
// TODO : n'escalader que sur la confiance faible est insuffisant ; une action
//        irréversible, sensible ou coûteuse doit AUSSI passer par un humain.
export function escalate(action) {
  return action.confidence < 0.7 ? 'ask-human' : 'proceed';
}

